#!/usr/bin/env python3
"""PreToolUse guard: deny direct Write/Edit access to machine-owned files,
hand-written stamp dates, machine-layer language violations and
unconfigured non-English payloads.

Six families of protected targets, each with its own remediation:
  1. The PMO database files: written only through the PMO CLI.
  2. Generated views: any file whose first line carries a generated-by
     marker (ba_compile render, vault_check render-decisions, future
     generators), and any
     path inside a _generated directory. Regenerate with the owning
     render command instead.
  3. Frozen analysis docs: paths listed in the freeze manifest
     (freeze.json) of an ACTIVE work order; a mid-order edit would fork
     the spec the order builds from.
  4. Locked records: authored files whose frontmatter carries
     'locked: true' (closed audit records; a new round is a new file).
  5. Hand-written stamp dates: a clock-owned stamp field
     (STAMP_FIELD_PATTERNS) is written only by its owning verb; a stamp
     date newly introduced by the model is denied outright, today's date
     included. Scripts write via subprocess and bypass this hook, so the
     owning verb is the sanctioned path.
  6. Language slices (Bash matcher plus paths): file paths under
     workspace/ and branch names are machine-layer English ASCII,
     always; git commit messages and gh pr title/body payloads must be
     ASCII unless the resolved project's terminology_language is
     configured non-English (the one config-aware slice; unreadable
     config fail-closes to English). output_language covers only .md
     body prose.

Families 5 and 6a apply only inside a resolved managed project's
workspace/ tree (paths judged relative to the project root, so a
non-ASCII ancestor directory outside the project never trips them).

A denial exits 2, which cancels the tool call and feeds the reason back
to the model. Everything else exits 0; a guard must never take a
session down on its own errors."""

from __future__ import annotations

import json
import re
import shlex
import sys
from pathlib import Path

import hook_common

GENERATED_MARKER_RE = re.compile(
    r"^<!-- generated by [a-z0-9_ .-]+; do not edit by hand -->"
)
LOCKED_RE = re.compile(r"^locked:\s*true\s*$")

# Clock-owned stamp fields, matched at line start. Any future stamp-like
# field registers its pattern here and gets an owning verb that writes
# the date itself (docs/authoring.md).
STAMP_FIELD_PATTERNS = (
    re.compile(r"^approved_at:\s*(\d{4}-\d{2}-\d{2})", re.MULTILINE),
    re.compile(r"^Status:\s+(?:approved|parked)\s+(\d{4}-\d{2}-\d{2})",
               re.MULTILINE),
    re.compile(r"^decided_at:\s*(\d{4}-\d{2}-\d{2})", re.MULTILINE),
)

GIT_COMMIT_RE = re.compile(r"\bgit\b[^|&;]*\bcommit\b")
# -m, combined short flags ending in m (-am), and --message[=] payloads.
COMMIT_MSG_RE = re.compile(
    r"(?:-[a-zA-Z]*m|--message=?)\s*(\"[^\"]*\"|'[^']*'|\S+)")
GH_PR_RE = re.compile(r"\bgh\b[^|&;]*\bpr\b[^|&;]*\b(?:create|edit)\b")
# --title/-t and --body/-b inline payloads; --body-file is a named
# residual exactly like commit's -F.
PR_PAYLOAD_RE = re.compile(
    r"(?:--title=?|--body=?|-t|-b)\s*(\"[^\"]*\"|'[^']*'|\S+)")
# Branch-creating commands; the name argument is machine layer, always
# ASCII. Deletion/list flags captured instead of a name are ASCII and
# pass harmlessly.
BRANCH_NAME_RES = (
    re.compile(r"\bgit\b[^|&;]*\bcheckout\s+-[bB]\s+([^\s|&;]+)"),
    re.compile(r"\bgit\b[^|&;]*\bswitch\s+-[cC]\s+([^\s|&;]+)"),
    re.compile(r"\bgit\b[^|&;]*\bbranch\s+([^\s|&;]+)"),
    re.compile(r"\bgit\b[^|&;]*\bworktree\s+add\b[^|&;]*\s-b\s+([^\s|&;]+)"),
)
UPGRADE_BRANCH_RE = re.compile(
    r"^agent-marketplace/upgrade-[a-z0-9][a-z0-9._-]*$"
)


def deny(message: str) -> int:
    print(f"pmo guard: {message}", file=sys.stderr)
    return 2


def session_upgrade_status(payload: dict) -> str:
    session_id = str(payload.get("session_id", ""))
    if not session_id:
        return ""
    try:
        value = json.loads(
            hook_common.session_state_path(session_id).read_text(encoding="utf-8")
        )
        return str(value.get("upgrade_status", "")) \
            if value.get("session_id") == session_id else ""
    except Exception:
        return ""


def is_upgrade_cli_command(payload: dict) -> bool:
    if payload.get("tool_name") != "Bash":
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", tool_input.get("cmd", "")) \
        if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(command, posix=True)
    except (TypeError, ValueError):
        return False
    if any(token in {";", "|", "||", "&&", ">", ">>", "<"} for token in argv):
        return False
    launcher = (hook_common.pmo_cli.data_dir() / "bin" / "pmo_cli.py").resolve()
    offset = 0
    if argv:
        try:
            if Path(argv[0]).expanduser().resolve(strict=False) == launcher:
                offset = 1
            elif len(argv) > 1 \
                    and re.fullmatch(r"python(?:3(?:\.\d+)?)?", Path(argv[0]).name) \
                    and Path(argv[1]).expanduser().resolve(strict=False) == launcher:
                offset = 2
        except OSError:
            return False
    if offset == 0:
        return False
    return len(argv) > offset + 1 and argv[offset] == "upgrade" \
        and argv[offset + 1] in {
            "status", "plan", "apply", "recover", "session-release",
        }


def fresh_upgrade_status(payload: dict) -> dict:
    resolved = hook_common.resolve_project(str(payload.get("cwd", "")))
    project = resolved[1] if resolved is not None else None
    try:
        return hook_common.pmo_cli.upgrade_core.status(
            hook_common.pmo_cli.data_dir(), hook_common.pmo_cli.db_path(),
            hook_common.pmo_cli.SCHEMA_VERSION, project,
            exclude_session_id=str(payload.get("session_id", "")),
        )
    except Exception as exc:
        return {
            "status": "AGENT_MARKETPLACE_UPGRADE_REQUIRED_BLOCKED",
            "blockers": [f"UPGRADE_STATUS_UNAVAILABLE:{exc}"],
        }


def is_upgrade_branch_command(payload: dict, status: dict) -> bool:
    blockers = {str(value) for value in status.get("blockers", [])}
    branch_blockers = {
        value for value in blockers if value.startswith("UPGRADE_BRANCH_REQUIRED:")
    }
    if not branch_blockers or blockers != branch_blockers \
            or payload.get("tool_name") != "Bash":
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", "") if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(command, posix=True)
    except (TypeError, ValueError):
        return False
    return bool(
        len(argv) == 4
        and argv[:3] in (["git", "switch", "-c"], ["git", "checkout", "-b"])
        and UPGRADE_BRANCH_RE.fullmatch(argv[3])
    )


def is_upgrade_target_command(payload: dict, status: dict) -> bool:
    blockers = {str(value) for value in status.get("blockers", [])}
    target_blockers = {
        value for value in blockers if value.startswith("UPGRADE_TARGET_REQUIRED:")
    }
    if len(target_blockers) != 1 or blockers != target_blockers \
            or payload.get("tool_name") != "Bash":
        return False
    tool_input = payload.get("tool_input", {})
    command = tool_input.get("command", "") if isinstance(tool_input, dict) else ""
    try:
        argv = shlex.split(command, posix=True)
    except (TypeError, ValueError):
        return False
    target = next(iter(target_blockers)).split(":", 1)[1]
    return argv in (["git", "switch", target], ["git", "checkout", target])


def frontmatter_locked(target: Path) -> bool:
    """True when the file opens with a YAML frontmatter block carrying
    'locked: true'."""
    try:
        with target.open("r", encoding="utf-8", errors="replace") as fh:
            if fh.readline().strip() != "---":
                return False
            for _ in range(40):  # frontmatter blocks are small
                line = fh.readline()
                if not line or line.strip() == "---":
                    return False
                if LOCKED_RE.match(line.strip()):
                    return True
    except Exception:
        return False
    return False


def frozen_by_work_order(target: Path, cwd: str) -> str | None:
    """Return the work-order key freezing this path, or None.

    Freeze manifests live at workspace/work-orders/<key>/freeze.json and
    hold repo-relative paths (a JSON list, or an object with a
    'frozen_paths' list). A manifest binds only while its work order is
    active; the team flow writes it, pmo only enforces it."""
    resolved = hook_common.resolve_project(cwd)
    if resolved is None:
        return None
    project_key, project_root = resolved
    orders_dir = (
        Path(project_root) / hook_common.project_workspace(Path(project_root))
        / "work-orders"
    )
    if not orders_dir.is_dir():
        return None
    manifests = sorted(orders_dir.glob("*/freeze.json"))
    if not manifests:
        return None
    try:
        con = pmo_cli.connect()
    except Exception:
        return None
    for manifest in manifests:
        try:
            data = json.loads(manifest.read_text(encoding="utf-8"))
        except Exception:
            continue
        paths = data.get("frozen_paths", []) if isinstance(data, dict) else data
        if not isinstance(paths, list):
            continue
        if not any(
            isinstance(p, str) and (Path(project_root) / p).resolve() == target
            for p in paths
        ):
            continue
        key = manifest.parent.name
        try:
            row = con.execute(
                "SELECT status FROM work_orders WHERE work_order_key = ?",
                (key,),
            ).fetchone()
        except Exception:
            continue
        if row and row["status"] in pmo_cli.ACTIVE_WO_STATUSES:
            return key
    return None


def project_relative(target: Path, cwd: str) -> Path | None:
    """The target's path relative to the resolved managed project's root,
    or None when the session is outside a managed project or the target
    is outside it."""
    resolved = hook_common.resolve_project(cwd)
    if resolved is None:
        return None
    _, project_root = resolved
    try:
        return target.relative_to(Path(project_root).resolve())
    except ValueError:
        return None


def stamped_dates(text: str) -> set[str]:
    found: set[str] = set()
    for pattern in STAMP_FIELD_PATTERNS:
        found.update(pattern.findall(text))
    return found


def hand_stamped_date(target: Path, written: dict) -> str | None:
    """Return a stamp-field date the model is introducing by hand, or
    None. Dates already present in the on-disk file are not introduced
    (rewrites and restructures of historical stamps pass); the value is
    irrelevant, today's date included: stamp fields are script-owned."""
    if target.suffix != ".md":
        return None
    new_text = str(written.get("content") or written.get("new_string")
                   or "")
    new_stamps = stamped_dates(new_text)
    if not new_stamps:
        return None
    old_text = target.read_text(encoding="utf-8", errors="replace") \
        if target.is_file() else ""
    introduced = new_stamps - stamped_dates(old_text)
    return sorted(introduced)[0] if introduced else None


def terminology_language(cwd: str) -> str:
    """The resolved project's configured terminology_language,
    lowercased; 'english' when unset or unreadable. Fail-closed: the
    default enforces the ASCII check, so a transient config error never
    admits non-ASCII text into immutable history."""
    try:
        resolved = hook_common.resolve_project(cwd)
        if resolved is None:
            return "english"
        _, project_root = resolved
        config_path = hook_common.project_config(Path(project_root))
        if config_path is None:
            return "english"
        config = json.loads(config_path.read_text(encoding="utf-8"))
        value = config.get("terminology_language")
        if isinstance(value, str) and value.strip():
            return value.strip().lower()
        return "english"
    except Exception:
        return "english"


def guard_bash(tool_input: dict, cwd: str) -> int:
    """Deny shell commands that name the PMO database file (the single
    writer is the CLI; sqlite3 or redirection against the file is a
    foreign write), branch names carrying non-ASCII text always (machine
    layer), and git commit / gh pr payloads carrying non-ASCII text
    unless the project's terminology_language is configured non-English.
    Only inline payloads are judged (-m/--message, --title/--body), so a
    compound command that also writes configured-language .md content
    passes; file-fed payloads (-F, --body-file) are named residuals."""
    command = str(tool_input.get("command", ""))
    try:
        import pmo_cli as _pmo
        if _pmo.DB_NAME in command:
            return deny(
                "this command names the PMO database file; the database is"
                " written only through the PMO CLI, and even reads go"
                " through its subcommands or the read-only dashboard. Use"
                " the CLI."
            )
    except Exception:
        pass
    for pattern in BRANCH_NAME_RES:
        for name in pattern.findall(command):
            if not name.isascii():
                return deny(
                    f"branch name '{name}' carries non-ASCII characters;"
                    " branch names are machine-layer English, never"
                    " configurable. Rename in English ASCII."
                )
    payloads = []
    if GIT_COMMIT_RE.search(command):
        payloads += COMMIT_MSG_RE.findall(command)
    if GH_PR_RE.search(command):
        payloads += PR_PAYLOAD_RE.findall(command)
    if all(p.isascii() for p in payloads):
        return 0
    if terminology_language(cwd) != "english":
        return 0
    return deny(
        "this git commit or gh pr payload carries non-ASCII text; commit"
        " messages and PR titles and bodies follow terminology_language,"
        " which resolves to English for this project (the default; also"
        " used when workspace/config.json cannot be read). Set"
        " terminology_language through the configure entry or rewrite the"
        " text in English. File names, branches and keys are always"
        " English."
    )


def main() -> int:
    payload = hook_common.normalize_payload(hook_common.read_payload())
    cached_upgrade = session_upgrade_status(payload)
    current_upgrade = fresh_upgrade_status(payload) if cached_upgrade else {}
    upgrade_status = (
        str(current_upgrade.get("status", ""))
        if cached_upgrade == "AGENT_MARKETPLACE_CURRENT" else cached_upgrade
    )
    if upgrade_status and upgrade_status != "AGENT_MARKETPLACE_CURRENT":
        if is_upgrade_cli_command(payload):
            hook_common.write_session_readiness(
                str(payload.get("session_id", "")), False, upgrade_status,
            )
        elif is_upgrade_branch_command(payload, current_upgrade) \
                or is_upgrade_target_command(payload, current_upgrade):
            hook_common.write_session_readiness(
                str(payload.get("session_id", "")), False, upgrade_status,
            )
        elif upgrade_status == "AGENT_MARKETPLACE_PROJECT_UPGRADE_PR_PENDING" \
                and payload.get("tool_name") == "Bash":
            # The team guard performs exact planned-path git validation.
            pass
        else:
            return deny(
                f"{upgrade_status}: normal marketplace mutations are locked;"
                " use Agent Marketplace Upgrade guidance. No files or project"
                " state were changed."
            )
    if payload.get("raw_tool_name") == "apply_patch" \
            and payload.get("patch_parse_error"):
        return deny(
            "the apply_patch payload could not be parsed safely ("
            + str(payload["patch_parse_error"])
            + "); the managed-file guard fails closed. Retry with a valid patch."
        )
    tool_input = payload.get("tool_input", {})
    if not isinstance(tool_input, dict):
        return 0
    if payload.get("tool_name") == "Bash":
        return guard_bash(tool_input, str(payload.get("cwd", "")))
    # The file families need the CLI module (db path, active-order lookup);
    # imported here so the Bash fast path never pays for it.
    global pmo_cli
    import pmo_cli
    for written in payload.get("file_targets", []):
        code = guard_file(written, payload)
        if code:
            return code
    return 0


def guard_file(written: dict, payload: dict) -> int:
    file_path = str(written.get("file_path", ""))
    if not file_path:
        return 0
    cwd = str(payload.get("cwd", ""))
    try:
        raw = Path(file_path)
        if not raw.is_absolute() and cwd:
            raw = Path(cwd) / raw
        target = raw.resolve()
        db = pmo_cli.db_path().resolve()
    except Exception:
        return 0
    if target == db or (target.parent == db.parent and target.name.startswith(db.name)):
        return deny(
            "the PMO database is written only through the PMO CLI;"
            " direct file writes are not allowed. Use the CLI subcommands."
        )
    resolved = hook_common.resolve_project(cwd)
    if resolved is not None:
        project_state = (
            Path(resolved[1]).resolve() / ".agentrof"
            / "agent-marketplace" / "project.json"
        )
        if target == project_state:
            return deny(
                "the Agent Marketplace project state is machine-owned and"
                " written only through PMO setup or upgrade commands; direct"
                " file writes are not allowed."
            )
    if "_generated" in target.parts:
        return deny(
            "this path is inside a _generated directory, which is"
            " machine-owned; hand edits would be lost. Change the authored"
            " docs and re-run the owning render command."
        )
    try:
        frozen_key = frozen_by_work_order(target, str(payload.get("cwd", "")))
        if frozen_key:
            return deny(
                f"this document is frozen by active work order '{frozen_key}'"
                " (its story claims rules or criteria this file owns);"
                " a mid-order edit would fork the running spec. Finish or"
                " release the work order first."
            )
    except Exception:
        pass
    try:
        if target.is_file():
            with target.open("r", encoding="utf-8", errors="replace") as fh:
                first_line = fh.readline()
            match = GENERATED_MARKER_RE.match(first_line.strip())
            if match:
                generator = first_line.split("generated by", 1)[1].split(";", 1)[0].strip()
                return deny(
                    f"this file is a GENERATED view (owner: {generator});"
                    " hand edits are not allowed and would be lost. Change"
                    " the source data or authored docs, then re-run the"
                    f" {generator.split()[0]} render command."
                )
            if frontmatter_locked(target):
                return deny(
                    "this record is locked (frontmatter 'locked: true'):"
                    " it is closed audit history and is never edited or"
                    " reopened. Continue in a new record instead. The one"
                    " sanctioned exception is a designation relabel of the"
                    " title and H1: vault_check.py reconcile-designations"
                    " --include-locked, owner-approved, one PMO audit"
                    " event per record."
                )
    except Exception:
        return 0
    try:
        rel = project_relative(target, str(payload.get("cwd", "")))
    except Exception:
        rel = None
    workspace = hook_common.project_workspace(Path(resolved[1])) \
        if resolved is not None else ""
    if rel is None or not rel.parts or rel.parts[0] != workspace:
        return 0
    if not str(rel).isascii():
        return deny(
            "this path carries non-ASCII characters; file and directory"
            " names are machine-layer English, never configurable. The"
            " language axes cover only .md bodies, names/terms, commits"
            " and PR bodies. Rename in English ASCII."
        )
    try:
        stamp = hand_stamped_date(target, written)
    except Exception:
        return 0
    if stamp:
        return deny(
            f"hand-written stamp date '{stamp}' in a clock-owned field"
            " (approved_at / Status approved|parked / decided_at): these"
            " fields are written only by their owning verb, never by hand,"
            " today's date included. Use ba_compile.py approve,"
            " landscape_check.py --stamp-engagement or vault_check.py"
            " stamp-decision; free dates elsewhere paste pmo_cli.py now"
            " --date output."
        )
    return 0


if __name__ == "__main__":
    sys.exit(main())
